import Cocoa

/// The menu bar glyph: the radar app icon in one colour. A rounded tile with the
/// screen cut out, a lightly tinted screen, a fading sweep, three blips and a centre dot.
/// Same geometry as `Resources/MenuBarIcon.svg` (generated by
/// `docs/wiki/attachments/gen-glyph.mjs`, variant `tileTint`); angles match the app icon.
/// Drawn in code so it stays sharp at any scale. Template images keep alpha, so the
/// tinted layers render as lighter shades of the system tint.
enum MenuBarIcon {
    private static let center = CGPoint(x: 9, y: 9)
    private static let screenRadius: CGFloat = 5.2

    /// A point at `radius` from the centre, `degrees` clockwise from straight up
    /// (the image is flipped, so y grows downwards as in the SVG).
    private static func point(_ radius: CGFloat, _ degrees: CGFloat) -> CGPoint {
        let t = (degrees - 90) * .pi / 180
        return CGPoint(x: center.x + radius * cos(t), y: center.y + radius * sin(t))
    }

    private static func fill(_ path: NSBezierPath, alpha: CGFloat) {
        NSColor.black.withAlphaComponent(alpha).setFill()
        path.fill()
    }

    private static func dot(_ radius: CGFloat, _ degrees: CGFloat, size: CGFloat) -> NSBezierPath {
        let p = point(radius, degrees)
        return NSBezierPath(ovalIn: NSRect(x: p.x - size, y: p.y - size, width: size * 2, height: size * 2))
    }

    static let image: NSImage = {
        let image = NSImage(size: NSSize(width: 18, height: 18), flipped: true) { _ in
            let r = screenRadius

            // Tile with the screen opening cut out.
            let tile = NSBezierPath(
                roundedRect: NSRect(x: 1.25, y: 1.25, width: 15.5, height: 15.5), xRadius: 3.6, yRadius: 3.6
            )
            tile.appendOval(in: NSRect(x: 9 - 6.1, y: 9 - 6.1, width: 12.2, height: 12.2))
            tile.windingRule = .evenOdd
            fill(tile, alpha: 1)

            // Tinted screen.
            fill(NSBezierPath(ovalIn: NSRect(x: 9 - r, y: 9 - r, width: r * 2, height: r * 2)), alpha: 0.28)

            // Sweep trail: nested wedges ending at the lead line (60°), 80° long, so
            // the overlap darkens towards the line.
            let lead: CGFloat = 60, span: CGFloat = 80, steps = 14
            for i in 0..<steps {
                let start = lead - span * (1 - CGFloat(i) / CGFloat(steps))
                let wedge = NSBezierPath()
                wedge.move(to: center)
                let segments = 24
                for s in 0...segments {
                    wedge.line(to: point(r, start + (lead - start) * CGFloat(s) / CGFloat(segments)))
                }
                wedge.close()
                fill(wedge, alpha: 0.058)
            }

            // Sweep line.
            let line = NSBezierPath()
            line.move(to: center)
            line.line(to: point(r, lead))
            line.lineWidth = 1.1
            line.lineCapStyle = .round
            NSColor.black.setStroke()
            line.stroke()

            // Blips (one bright, two fading) and the centre dot.
            fill(dot(r * 0.74, 32, size: 1.05), alpha: 1)
            fill(dot(r * 0.55, -62, size: 0.75), alpha: 0.7)
            fill(dot(r * 0.6, 150, size: 0.7), alpha: 0.5)
            fill(dot(0, 0, size: 0.8), alpha: 1)
            return true
        }
        image.isTemplate = true
        return image
    }()
}
